/* Two standalone adventures join the four study chapters. */
'use strict';
const AA=AwayAdventure;
const AwayScenes=[
 {id:'seaside',name:'贝壳来信湾',tag:'第五章 · 海边寻信',image:'assets/away-seaside.png',description:'浅青海水、奶油色沙滩和一间等着来信的小屋。',tasks:['修复海风铃','点亮归航路','寄出夏日来信'],items:[{id:'pearl',icon:'🐚',name:'珍珠白贝壳',x:42,y:64},{id:'coral',icon:'🪸',name:'珊瑚红碎片',x:54,y:77},{id:'amber',icon:'💎',name:'琥珀海玻璃',x:64,y:56}],targets:[{id:'chime',name:'海风铃架',icon:'🎐',x:21,y:32}],symbols:[['shell','🐚','贝壳'],['wave','🌊','浪花'],['bird','🕊','海鸥']]},
 {id:'winter',name:'铃铛不眠街',tag:'第六章 · 雪夜送暖',image:'assets/away-winter.png',description:'深蓝雪夜里，一座亮着姜饼色灯光的圣诞小镇。',tasks:['送达三份礼物','点亮不眠街','奏响雪夜钟声'],items:[{id:'red',icon:'🎁',name:'红缎带礼物',x:29,y:32},{id:'green',icon:'🎁',name:'绿缎带礼物',x:51,y:40},{id:'gold',icon:'🎁',name:'金缎带礼物',x:83,y:73}],targets:[{id:'bakery',name:'烘焙屋 · 红缎带',icon:'🥐',x:24,y:48},{id:'station',name:'驿站 · 绿缎带',icon:'🚂',x:83,y:25},{id:'tree',name:'圣诞树 · 金缎带',icon:'🎄',x:65,y:55}],symbols:[['star','⭐','星星'],['bell','🔔','铃铛'],['moon','🌙','月亮']]}
];
let activeAwayScene=null,selectedAwayItem=null,awayBackground=[];
function awayProgress(id){state.awayGames??={};return state.awayGames[id]??=AA.fresh();}
const adventureRestore=L.restore;
L.restore=function(raw){const s=adventureRestore(raw);if(!s)return null;if(s.awayGames!==undefined&&(!s.awayGames||typeof s.awayGames!=='object'||Array.isArray(s.awayGames)||Object.entries(s.awayGames).some(([id,p])=>!AA.validate(p,id))))return null;return s;};
function awayCards(){return `<div class="away-cards">${AwayScenes.map(scene=>{const s=awayProgress(scene.id);return `<button data-away-scene="${scene.id}" class="away-card" style="--away-image:url('${scene.image}')"><span>${esc(scene.tag)} · 独立冒险</span><strong>${esc(scene.name)}</strong><small>${s.completed?'✓ 已通关，仍可回来逛逛':'任务 '+Math.min(s.stage+1,3)+'/3 · '+esc(scene.tasks[Math.min(s.stage,2)])} ↗</small></button>`;}).join('')}</div>`;}
function bindAwayCards(){document.querySelectorAll('[data-away-scene]').forEach(el=>el.onclick=()=>openAwayScene(el.dataset.awayScene));}
showChapterMap=function(){const course=currentCourse();if(!course){showAwayMap(true);return;}const s=studyState();modal(`<span class="eyebrow">六段旅程 · 各自启程</span><h2 id="dialogTitle">今天，想去哪里冒险？</h2><p>所有章节都可直接进入，各自保留进度。学习章节的小节按顺序推进，本章测验达到90%记为通关；第五、六章是没有课程题目的独立冒险。</p><div class="chapter-atlas">${course.chapters.map((ch,i)=>{const all=ch.sections.flatMap(sec=>sec.lessons),count=all.filter(l=>s.deposited.includes(l.id)).length,best=s.assessments.filter(a=>a.chapter===i).sort((a,b)=>b.correct/b.total-a.correct/a.total)[0];return `<button data-enter-chapter="${i}" class="chapter-map-card" style="--chapter-image:url('assets/world-${ch.zone}.webp')"><span>第 ${i+1} 章 · 独立学习冒险</span><strong>${esc(ch.title)}</strong><small>${esc(ch.english)}</small><p>知识 ${count}/${all.length}${best?' · 本章测验 '+Math.floor(best.correct/best.total*100)+'%':''}</p></button>`;}).join('')}</div>${awayCards()}<div class="actions"><button id="continueChapter" class="primary">继续当前章节</button><button id="courseFromAPI">用我的资料生成课程</button></div>`,true);document.querySelectorAll('[data-enter-chapter]').forEach(el=>el.onclick=()=>{closeAwayScene();enterStudyChapter(+el.dataset.enterChapter);});bindAwayCards();$('continueChapter').onclick=close;$('courseFromAPI').onclick=showCourseImporter;save();};
function showAwayMap(onlyAway=false){if(currentCourse()&&!onlyAway){showChapterMap();return;}modal(`<span class="eyebrow">独立冒险章节</span><h2 id="dialogTitle">选择一段旅程</h2>${awayCards()}<div class="actions"><button id="awayMapBack">返回场景</button></div>`,true);bindAwayCards();$('awayMapBack').onclick=close;}
function closeAwayScene(){const el=$('awayScene');if(!el)return;el.remove();for(const[node,wasInert]of awayBackground)node.inert=wasInert;awayBackground=[];activeAwayScene=null;state.activeAdventure=null;selectedAwayItem=null;document.body.classList.remove('away-open');$('awayDestinations')?.focus();save();}
function awayFeedback(text){$('awayNote').textContent=text;}
function collectAwayItem(id){if(AA.take(awayProgress(activeAwayScene),activeAwayScene,id)){selectedAwayItem=id;save();openAwayScene(activeAwayScene,'已收入背包。选中素材，再点击目的地；也可以拖过去。');}}
function deliverAwayItem(id,target){const scene=activeAwayScene,s=awayProgress(scene);if(!s.bag.includes(id))AA.take(s,scene,id);if(!AA.place(s,scene,id,target)){save();awayFeedback(scene==='winter'?'缎带和收件处没有对上，礼物仍在背包里。':'先找到碎片，再把它挂到海风铃架。');return;}selectedAwayItem=null;save();openAwayScene(scene,s.stage===1?'第一项任务完成！下一项装置已经出现。':'放好了，继续寻找剩下的物件。');}
function stageWorld(scene,s){if(s.stage===0)return scene.items.filter(item=>!s.bag.includes(item.id)&&!s.placed.includes(item.id)).map(item=>`<button class="away-spot away-item item-${item.id}" data-away-item="${item.id}" draggable="true" style="left:${item.x}%;top:${item.y}%"><i>${item.icon}</i><span>${esc(item.name)}</span></button>`).join('')+scene.targets.map(t=>`<button class="away-spot away-target" data-away-target="${t.id}" data-drop="away-${t.id}" style="left:${t.x}%;top:${t.y}%"><i>${t.icon}</i><span>${esc(t.name)} ${scene.id==='seaside'?s.placed.length+'/3':s.placed.some(id=>AA.rules.winter.targets[id]===t.id)?'✓':''}</span></button>`).join('');
 if(s.stage===1&&scene.id==='seaside')return `<div class="away-puzzle world-puzzle"><h3>归航路的三面航标</h3><p>码头刻着路线：<b>东 → 南 → 西</b>。依次转动三面航标。</p><div class="away-dials">${s.dials.map((n,i)=>`<button data-away-dial="${i}" aria-label="转动第${i+1}面航标"><strong>${['↑','→','↓','←'][n]}</strong><small>航标 ${i+1} · ${['北','东','南','西'][n]}</small></button>`).join('')}</div><button id="awayCheck" class="primary">试亮航灯</button></div>`;
 if(s.stage===1)return `<div class="away-puzzle world-puzzle"><h3>让三盏街灯同时亮起</h3><p>开关会同时翻转对应的灯。橱窗里画着每个开关连向哪里。</p><div class="away-lamps">${s.lights.map((on,i)=>`<span class="${on?'lit':''}">${on?'💡':'○'}<small>街灯 ${i+1}</small></span>`).join('')}</div><div class="away-dials">${['连接灯1、2','连接灯2、3','连接全部灯'].map((t,i)=>`<button data-away-switch-light="${i}">开关 ${i+1}<small>${t}</small></button>`).join('')}</div><button id="awayCheck" class="primary">确认整街亮灯</button></div>`;
 if(s.stage===2)return `<div class="away-puzzle world-puzzle"><h3>${scene.id==='seaside'?'明信片上的暗号':'广场乐谱上的暗号'}</h3><p>${scene.id==='seaside'?'先捡起贝壳，经过浪花，最后让海鸥捎信。':'星星亮起，铃铛回响，月亮道晚安。'}</p><div class="away-sequence">${s.sequence.map(id=>scene.symbols.find(x=>x[0]===id)[1]).join('　')||'等待你的三个音符'}</div><div class="away-dials">${scene.symbols.map(([id,icon,label])=>`<button data-away-symbol="${id}">${icon}<small>${label}</small></button>`).join('')}</div><div class="actions"><button id="awayClear">重新排列</button><button id="awayFinish" class="primary">${scene.id==='seaside'?'投进漂流信箱':'奏响雪夜钟声'}</button></div></div>`;
 return `<div class="away-puzzle world-puzzle away-win"><span>✦ 本章通关 ✦</span><h3>${scene.id==='seaside'?'海风铃响了，来信也启程了。':'灯光和钟声，把暖意送到了。'}</h3><p>三项任务全部完成，共 ${s.moves} 次探索操作。你可以随时去其他章节，或回来重看这片风景。</p><button id="awayWinMap" class="primary">选择其他章节</button></div>`;}
function taskHint(scene,s){return s.stage===0?(scene.id==='seaside'?'找到三枚碎片，挂到海风铃架。':'找到三份礼物，按缎带颜色送到对应收件处。'):s.stage===1?(scene.id==='seaside'?'转动航标，照亮东、南、西的归航路线。':'使用三个联动开关，让三盏街灯同时亮起。'):s.stage===2?'阅读装置上的线索，按顺序完成最后的暗号。':'本章已完成，其他章节也随时为你开放。';}
function openAwayScene(id,message=''){const scene=AwayScenes.find(s=>s.id===id);if(!scene)return;if(activeAwayScene!==id)selectedAwayItem=null;activeAwayScene=id;state.activeAdventure=id;const s=awayProgress(id);close();$('awayScene')?.remove();const el=document.createElement('section');el.id='awayScene';el.className='away-scene away-'+id;el.setAttribute?.('role','dialog');el.setAttribute?.('aria-modal','true');el.setAttribute?.('aria-labelledby','awayTitle');
 el.innerHTML=`<div class="away-toolbar"><div><span>${esc(scene.tag)} · 独立冒险</span><h2 id="awayTitle">${esc(scene.name)}</h2></div><div class="away-switches"><button id="awayAllChapters">六章地图</button>${AwayScenes.map(x=>`<button data-away-switch="${x.id}" ${x.id===id?'aria-current="page"':''}>${esc(x.name)}</button>`).join('')}<button id="awayReturn">返回原章节 ×</button></div></div><div class="away-taskbar">${scene.tasks.map((t,i)=>`<span class="${i===s.stage?'active':i<s.stage?'complete':''}">${i<s.stage?'✓':i+1} ${esc(t)}</span>`).join('')}</div><div class="away-landscape"><img src="${scene.image}" alt="${esc(scene.description)}" draggable="false">${stageWorld(scene,s)}<div class="away-weather" aria-hidden="true">${id==='winter'?Array.from({length:16},(_,i)=>`<i style="--x:${i*37%100}%;--delay:-${i%9}s;--duration:${7+i%5}s">❄</i>`).join(''):''}</div></div><div class="away-playbar"><div><span class="eyebrow">${s.completed?'通关纪念':'任务 '+(s.stage+1)+'/3'}</span><p id="awayNote" aria-live="polite">${esc(message||taskHint(scene,s))}</p></div><div class="away-bag"><strong>随身小包</strong>${scene.items.filter(item=>s.bag.includes(item.id)).map(item=>`<button data-away-bag="${item.id}" draggable="true" class="${selectedAwayItem===item.id?'selected':''}">${item.icon} ${esc(item.name)}</button>`).join('')||'<small>收集的物件会放在这里</small>'}</div></div>`;
 document.body.appendChild(el);if(!awayBackground.length){awayBackground=[...document.querySelectorAll('body > header, body > main, #fieldNote')].map(node=>[node,node.inert]);for(const[node]of awayBackground)node.inert=true;}document.body.classList.add('away-open');$('awayReturn').onclick=closeAwayScene;$('awayAllChapters').onclick=()=>{closeAwayScene();showChapterMap();};if($('awayWinMap'))$('awayWinMap').onclick=$('awayAllChapters').onclick;
 document.querySelectorAll('[data-away-switch]').forEach(node=>node.onclick=()=>{save();openAwayScene(node.dataset.awaySwitch);});document.querySelectorAll('[data-away-item]').forEach(node=>{node.onclick=()=>collectAwayItem(node.dataset.awayItem);bindDraggable(node,{awayScene:id,awayItem:node.dataset.awayItem});});document.querySelectorAll('[data-away-bag]').forEach(node=>{node.onclick=()=>{selectedAwayItem=node.dataset.awayBag;openAwayScene(id,'已选中，点击对应目的地即可放入。');};bindDraggable(node,{awayScene:id,awayItem:node.dataset.awayBag});});document.querySelectorAll('[data-away-target]').forEach(node=>{node.onclick=()=>selectedAwayItem?deliverAwayItem(selectedAwayItem,node.dataset.awayTarget):awayFeedback('先点击收集一个物件，或直接把物件拖到这里。');bindDrop(node,'away-'+node.dataset.awayTarget);});
 document.querySelectorAll('[data-away-dial]').forEach(node=>node.onclick=()=>{AA.turn(s,id,+node.dataset.awayDial);save();openAwayScene(id);});document.querySelectorAll('[data-away-switch-light]').forEach(node=>node.onclick=()=>{AA.toggle(s,id,+node.dataset.awaySwitchLight);save();openAwayScene(id);});if($('awayCheck'))$('awayCheck').onclick=()=>{if(AA.check(s,id)){save();openAwayScene(id,'装置启动了，最后的任务已经出现。');}else awayFeedback('还差一点，看看装置旁的线索，再试一次。');};
 document.querySelectorAll('[data-away-symbol]').forEach(node=>node.onclick=()=>{if(AA.press(s,id,node.dataset.awaySymbol)){save();openAwayScene(id);}else awayFeedback('已经放了三个符号，可以提交或重新排列。');});if($('awayClear'))$('awayClear').onclick=()=>{AA.resetSequence(s);save();openAwayScene(id);};if($('awayFinish'))$('awayFinish').onclick=()=>{if(AA.finish(s,id)){save();openAwayScene(id);}else awayFeedback('暗号还没有对上。读一读线索，重新排列后再试。');};
 el.addEventListener('keydown',event=>{event.stopPropagation();if(event.key==='Escape'){event.preventDefault();closeAwayScene();}if(event.key==='Tab'){const buttons=el.querySelectorAll?.('button');if(!buttons?.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});$('awayReturn').focus();save();
}
const adventureDrag=applyDrag;
applyDrag=function(data,kind,category){if(data?.awayItem){if(data.awayScene!==activeAwayScene||!kind.startsWith('away-'))return;deliverAwayItem(data.awayItem,kind.slice(5));return;}adventureDrag(data,kind,category);};
$('awayDestinations').textContent='六章地图';$('awayDestinations').onclick=showChapterMap;
$('seasideButton').onclick=()=>openAwayScene('seaside');$('winterButton').onclick=()=>openAwayScene('winter');
const adventureInit=initExamWorld;
initExamWorld=function(){const resume=state.activeAdventure;adventureInit();if(AwayScenes.some(scene=>scene.id===resume))openAwayScene(resume);};
